        if (dts_Item.getCellData(1, subArr[1]) == '1') {
            var temp = scwin.fnGetCodeName(subArr[0]);
            if (temp == '') continue;
            if (!isue_prev) {
                scwin.isueText += temp;
                scwin.isueSearchText += "" + subArr[0];
            } else {
                scwin.isueText += ("/" + temp);
                scwin.isueSearchText += ',' + subArr[0];
            }
            isue_prev = true;
        }
        if (dts_Item.getCellData(1, subArr[2]) == '1') {
            var temp = scwin.fnGetCodeName(subArr[0]);
            if (temp == '') continue;
            if (!napprov_prev) {
                napprovText += temp;
                napprovSearchText += "" + subArr[0];
            } else {
                napprovText += ("/" + temp);
                napprovSearchText += ',' + subArr[0];
            }
            napprov_prev = true;
        }
    }
};
scwin.fnGetCodeName = function(pCode) {
    var text = '';
    for (var idx = 1; idx < dts_Cod.getTotalRow(); idx++) {
        var code = dts_Cod.getCellData(idx, "VALUE");
        if (code == pCode) {
            text.setValue(dts_Cod.getCellData(idx, "TEXT"));
        }
    }
    return text;
};
scwin.fn_parentRefresh = async function() {
    var arrPar = new Array();
    scwin.fn_save();
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = {
            ISUE: scwin.isueText,
            NAPPROV: napprovText,
            ISUE_SEARCH_TEXT: scwin.isueSearchText,
            NAPPROV_SEARCH_TEXT: napprovSearchText,
            DTS_ISSUE: dts_Item
        };
        scwin.fn_SetPar(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var arrPar = new Array();
    scwin.fn_GetPar = $c.frame.path("../").scwin.fn_GetPar;
    scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
        var obj = arrPar[0];
        $c.stf.CopyDataSet(obj, dts_Item);
        dts_Item.ResetStatus();
    }
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='COMITE_INVSTG_ISUE_CONTN_TP_CD'";
    /* var	url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=CODE_M_IN&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01 +"&SCREN_ID=" +vScrenID+
    			 "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + 
    			 "&queryId=lds.stf.lstinvstg.prelminvstg.comitedelib.select.comite_invstg_isue_contn_tp_cd.list"+ 
    			 "&{P}CD_ID_M=COMITE_INVSTG_ISUE_CONTN_TP_CD";
    			 */

    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    //alert(dts_Cod.Text);

};
